  "prompt": "prompts/physics_committee_luna_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B024",
      "proposed_laureates": ["Francis Halzen"],
      "assessment": {
        "nobel_worthiness": "IceCube established high-energy neutrino astronomy, opening a new observational window on the most energetic processes in the Universe. The discovery and subsequent measurements have lasting significance.",
        "attribution": "Halzen's role in developing and leading the IceCube effort is central. The result depended on a large collaboration, so the individual credit reflects scientific leadership rather than sole experimental work.",
        "maturity": "The astrophysical neutrino signal has been confirmed through multiple observations over many years and is now a mature field.",
        "uncertainties": ["The discovery was a major collective achievement, and a single laureate cannot represent all contributors."]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B025",
      "proposed_laureates": ["Hidetoshi Katori", "Jun Ye"],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have transformed precision timekeeping and tests of fundamental physics, with accuracy that enables new measurements of gravitational potential and physical constants.",
        "attribution": "Katori and Ye made distinct, foundational contributions to clock architectures and their experimental realization. The broader clock community has since developed the technology.",
        "maturity": "The method is well established, independently reproduced, and continues to improve in performance and applications.",
        "uncertainties": ["The boundary between the original clock breakthroughs and subsequent community-wide advances merits care."]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B001",
      "proposed_laureates": ["Jon Magne Leinaas", "Gwendal Fève", "Moty Heiblum"],
      "assessment": {
        "nobel_worthiness": "Fractional charge and anyonic exchange statistics reveal fundamental properties of two-dimensional quantum matter and have driven a major experimental field.",
        "attribution": "Leinaas provided early theoretical work on anyonic statistics; Fève's shot-noise measurements and Heiblum's experiments helped establish fractional charge and probe anyonic behavior. Credit must span theory and experiment.",
        "maturity": "Fractional charge is firmly established. Experimental evidence for anyonic statistics has advanced substantially, though the most direct demonstrations are relatively recent.",
        "uncertainties": ["The experimental case for anyonic statistics is newer and less settled than the evidence for fractional charge; the combined discovery spans many contributors."]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B014",
      "proposed_laureates": ["Juan Ignacio Cirac", "Peter Zoller", "Rainer Blatt"],
      "assessment": {
        "nobel_worthiness": "Trapped ions made quantum information processing experimentally concrete and enabled exceptional control of individual quantum systems, with lasting influence on quantum science.",
        "attribution": "Cirac and Zoller supplied foundational proposals, while Blatt's experiments demonstrated key operations and control. These complementary contributions make a strong, coherent case.",
        "maturity": "Trapped-ion control and entanglement are repeatedly demonstrated and underpin a mature research platform, even as scalable computing remains in development.",
        "uncertainties": ["The broader field of quantum computing includes many platforms and contributors; the prize scope should remain on the trapped-ion foundations."]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B023",
      "proposed_laureates": ["Chryssa Kouveliotou", "Robert C. Duncan", "Christopher Thompson"],
      "assessment": {
        "nobel_worthiness": "The identification of magnetars as neutron stars powered by ultra-strong magnetic fields explained a striking class of high-energy sources and reshaped neutron-star astrophysics.",
        "attribution": "Kouveliotou's observations established the magnetar connection, while Duncan and Thompson developed the influential physical model. The discovery and explanation warrant joint recognition.",
        "maturity": "Magnetars are now a well-established source class supported by decades of observations and a broad range of phenomena.",
        "uncertainties": ["Some magnetar emission mechanisms remain unsettled, although the basic source identification is secure."]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B038",
      "proposed_laureates": ["Charles L. Bennett", "David N. Spergel", "Lyman A. Page Jr."],
      "assessment": {
        "nobel_worthiness": "WMAP's precise mapping of the cosmic microwave background made cosmological parameters measurable with new confidence and established a reference picture of the early Universe.",
        "attribution": "Bennett and Page were central to the mission and its measurements, while Spergel played a major role in extracting cosmological implications. The mapping was a large team effort.",
        "maturity": "The measurements have been extensively checked against later observations, including Planck, and their influence on cosmology is secure.",
        "uncertainties": ["WMAP refined a field already transformed by COBE; the distinction between a decisive new result and a major precision advance should be weighed."]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B007",
      "proposed_laureates": ["Maura McLaughlin", "Michael Kramer", "Richard N. Manchester"],
      "assessment": {
        "nobel_worthiness": "Pulsar timing arrays may have opened a new gravitational-wave frequency band and could reveal a population of massive black-hole binaries across cosmic history.",
        "attribution": "These scientists have made sustained, central contributions to pulsar timing and the international efforts that detected a common low-frequency signal. The result is inherently collaborative.",
        "maturity": "Multiple timing-array collaborations report a common-spectrum process consistent with a gravitational-wave background, but the astrophysical interpretation is still developing.",
        "uncertainties": ["The evidence and source attribution are not yet as conclusive as a direct, individually resolved gravitational-wave detection."]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B012",
      "proposed_laureates": ["Alan H. Guth", "Andrei Linde", "Viatcheslav Mukhanov"],
      "assessment": {
        "nobel_worthiness": "Inflation and the quantum origin of cosmic structure provide a powerful framework for explaining the Universe's large-scale properties and the seeds of galaxies.",
        "attribution": "Guth and Linde developed influential inflationary ideas, and Mukhanov made foundational contributions to the theory of primordial fluctuations. Credit is necessarily shared across a broad theoretical community.",
        "maturity": "The framework has guided cosmology for decades, but it has not yet been confirmed by a unique observational signature.",
        "uncertainties": ["Many inflationary models remain viable, and current observations do not establish inflation or identify a specific mechanism."]
      }
    }
  ]
}
